// Mention Verification (weekly). Re-checks live citations and sets seen_in_ai
// ONLY when the same entity's citation_url appears, exactly, in that entity's
// AI-platform probe source_urls. Fetches are SSRF-guarded.
const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const http = this.helpers.httpRequest;
if (!SB_URL || !SB_KEY) return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({ url: SB_URL + '/rest/v1/' + path, json: true }, opts, {
    headers: Object.assign({ apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' }, opts.headers || {}),
  }));
}
function normDomain(d) { if (!d) return ''; return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim(); }
function textIncludes(t, n) { if (!t || !n) return false; return String(t).toLowerCase().includes(String(n).toLowerCase()); }
// Canonical URL key for EXACT comparison (scheme/host-www/trailing-slash/fragment-insensitive).
function urlKey(u) {
  try {
    const x = new URL(u);
    let host = x.host.toLowerCase().replace(/^www\./, '');
    let path = x.pathname.replace(/\/+$/, '');
    return host + path + (x.search || '');
  } catch (e) { return String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[#].*$/, '').replace(/\/+$/, ''); }
}
// SSRF guard: only allow public https hostnames. Reject IP literals, private
// suffixes, embedded credentials and non-443 ports. Caller also disables
// redirects so a public URL cannot bounce to an internal address.
function ssrfReason(u) {
  let x;
  try { x = new URL(u); } catch (e) { return 'unparseable URL'; }
  if (x.protocol !== 'https:') return 'non-https scheme';
  if (x.username || x.password) return 'embedded credentials';
  if (x.port && x.port !== '443') return 'non-standard port';
  const host = x.hostname.toLowerCase();
  if (host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local') || host.endsWith('.internal')) return 'internal hostname';
  // Reject IPv6 literals outright, and IPv4 literals (citations should be domain names).
  if (host.indexOf(':') !== -1) return 'ipv6 literal host';
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return 'ip-literal host';
  if (!host.includes('.')) return 'non-fqdn host';
  return null; // safe
}

const live = await rest('citation_targets?select=id,entity_id,citation_url,name,tracked_entities(name,domain)&status=eq.live&citation_url=not.is.null');
if (!live.length) return [{ json: { note: 'no live citations to verify' } }];

// Map query -> entity, then build per-entity set of AI-platform source URL keys.
const queries = await rest('target_queries?select=id,entity_id');
const entityByQuery = {}; for (const q of queries) entityByQuery[q.id] = q.entity_id;
// AI platforms only — exclude plain 'google' organic results.
const aiChecks = await rest('visibility_checks?select=query_id,platform,source_urls&platform=in.(google_ai_overview,perplexity,chatgpt,gemini,claude)');
const urlsByEntity = {};
for (const ch of aiChecks) {
  const eid = entityByQuery[ch.query_id]; if (!eid) continue;
  const urls = Array.isArray(ch.source_urls) ? ch.source_urls : [];
  const set = (urlsByEntity[eid] = urlsByEntity[eid] || {});
  for (const u of urls) set[urlKey(u)] = true;
}

const out = [];
const rows = [];
for (const t of live) {
  const ent = Array.isArray(t.tracked_entities) ? t.tracked_entities[0] : t.tracked_entities;
  const name = ent && ent.name ? ent.name : '';
  const dom = ent && ent.domain ? normDomain(ent.domain) : '';
  let isLive = false;
  let note = '';

  const reason = ssrfReason(t.citation_url);
  if (reason) {
    note = 'citation_url not fetched (SSRF guard: ' + reason + ')';
  } else {
    try {
      const html = await http({
        url: t.citation_url,
        json: false,
        timeout: 10000,
        maxRedirects: 0, // do not follow redirects (prevents redirect-to-internal)
        headers: { 'User-Agent': 'LIT-VisibilityEngine/1.0' },
      });
      const text = String(html).replace(/<[^>]+>/g, ' ');
      isLive = textIncludes(text, name) || (dom && textIncludes(text, dom));
      note = isLive ? 'citation_url resolves and still mentions us' : 'citation_url resolves but mention not found';
    } catch (e) {
      note = 'citation_url did not resolve / redirected: ' + String((e && e.message) || e);
    }
  }

  // Same entity + AI platforms + EXACT normalized URL match.
  const entSet = urlsByEntity[t.entity_id] || {};
  const seenInAi = Boolean(entSet[urlKey(t.citation_url)]);
  if (seenInAi) note += '; appears in this entity’s AI-platform source_urls (feeding AI answers)';

  rows.push({ citation_target_id: t.id, is_live: isLive, seen_in_ai: seenInAi, note: note });
  out.push({ json: { target: t.name, citation_url: t.citation_url, is_live: isLive, seen_in_ai: seenInAi, note: note } });
}
if (rows.length) await rest('mention_checks', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: rows });
return out;
